using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ChooseTargetStateMouseAction", menuName = "Data/Battle/Actions/ChooseTargetStateMouseAction")]
public class ChooseTargetStateMouseAction : ChooseTargetStateAction
{
	public override void Execute(float d)
	{
		base.inputManager.MouseInput(delegate(GameObject gameObject)
		{
			TargetInstance component = gameObject.GetComponent<TargetInstance>();
			if (component != null)
			{
				if (chooseSelf)
				{
					if (component.transform.parent.gameObject != base.actionInstance.ActionOwner)
					{
						base.noValidRaycastMouseInputAction();
						return;
					}
				}
				else if (!targetUnits.Contains(component.TargetEnum))
				{
					base.noValidRaycastMouseInputAction();
					return;
				}
				TargetSelected(component);
			}
			else
			{
				base.noValidRaycastMouseInputAction();
			}
		}, base.noValidRaycastMouseInputAction, base.beforeRaycastCheck);
	}
}
